/* @autogenerated */
import { isDevMode } from '@angular/core';
import { AppConfigService } from '@shared/context/config/app-config.service';
import { AuthConfig, OAuthService } from 'angular-oauth2-oidc';
import { Observable, ReplaySubject, combineLatest } from 'rxjs';
import { IdentityErrorReason, IdentityHandler, IdentityProvider, IdentityUiPort } from '../identity-provider.interface';
import { AppStateService } from '@shared/context/state/app-state.service';
import { ErrorService } from '@shared/context/observability/error.service';
import { UserInfo } from '../user-info.model';

const DEFAULT_ROLES_CLAIM = 'groups';

export class OidcIdentityProviderService implements IdentityProvider {
  constructor(
    private oauthService: OAuthService,
    private config: AppConfigService,
    private appState: AppStateService,
    private errors: ErrorService,
    private ui: IdentityUiPort,
  ) {}

  accept(type: string, name: string): IdentityHandler | null {
    if (type === 'oidc') {
      const result = new OidcIdentityHandlerService(
        name,
        this.oauthService,
        this.config,
        this.appState,
        this.errors,
        this.ui,
      );
      result.configure();
      return result;
    } else {
      return null;
    }
  }
}

export class OidcIdentityHandlerService implements IdentityHandler {
  private logged: boolean | undefined = undefined;
  private boostrapSubject = new ReplaySubject<void>();
  private currentUser: UserInfo = {};
  private rolesClaim = DEFAULT_ROLES_CLAIM;
  constructor(
    private readonly name: string,
    private readonly oauthService: OAuthService,
    private readonly config: AppConfigService,
    private readonly appState: AppStateService,
    private readonly errors: ErrorService,
    private readonly ui: IdentityUiPort,
  ) {
    // Los eventos no listados se ignoran: pueden llevar claims y console.log acaba en el colector de logs
    this.oauthService.events.subscribe((e) => {
      if (e.type === 'user_profile_load_error') {
        this.resetCredentialsIfConfirmed('profile');
      } else if (e.type === 'code_error') {
        this.ui.notifyError('code');
      } else if (e.type === 'token_received') {
        this.updateToken();
      } else if (e.type === 'logout') {
        this.appState.userInfo[this.name].set({});
      } else if (e.type === 'invalid_nonce_in_state') {
        this.oauthService.initCodeFlow();
      } else if (e.type === 'silently_refreshed') {
        this.incomingLogin();
      } else if (e.type === 'token_refresh_error') {
        this.resetUser();
      } else if (e.type === 'discovery_document_load_error') {
        this.resetCredentialsIfConfirmed('discovery');
      } else if (e.type === 'silent_refresh_error') {
        this.oauthService.logOut(true);
        this.appState.userInfo[this.name].set({});
      }
    });
  }

  bootstrap(): Observable<void> {
    return this.boostrapSubject;
  }

  login(): void {
    this.oauthService.initCodeFlow();
  }

  logout(): void {
    // RP-Initiated Logout: the end_session_endpoint revokes the session tokens. The RFC 7009
    // revocation endpoint is only for confidential clients and rejects the SPA with 401.
    this.oauthService.logOut();
  }

  public configure() {
    const arr: Observable<any>[] = [this.appState.tenant, this.config['identity.' + this.name]];
    combineLatest(arr).subscribe((vals: any[]) => {
      this.configureForTenant(vals[0] as string, vals[1]);
    });
  }

  private configureForTenant(tenant: string, setup: any) {
    if ('pkce' in setup) {
      console.warn(`identity.${this.name}.pkce is ignored: PKCE is always enabled`);
    }
    this.rolesClaim = setup['roles-claim'] ?? DEFAULT_ROLES_CLAIM;
    const config: AuthConfig = {
      responseType: 'code',
      redirectUri: setup['redirect'] ?? this.currentUrl(),
      // Must be one of the client's allowed logout redirects (exact match at the auth-server)
      postLogoutRedirectUri: setup['logout-redirect'] ?? window.location.origin + '/',
      issuer: this.forCurrent(setup['issuer'], tenant),
      requireHttps: !!setup['force-https'],
      // The SPA's id. The SPA is registered with this id at the auth-server
      clientId: setup['client-id'],
      // Used as is: include offline_access to get the refresh token
      scope: setup['scope'],
      // set to true, to receive also an id_token via OpenId Connect (OIDC) in addition to the
      // OAuth2-based access_token
      oidc: true,
      timeoutFactor: 0.75,
      // Refresh with the refresh token, not with the silent-refresh iframe
      useSilentRefresh: false,
      showDebugInformation: isDevMode() && setup['debug'] === true,
      disablePKCE: false,
    };
    if (setup['audience']) {
      config.customQueryParams = {
        audience: setup['audience'],
      };
    }
    // localStorage keeps the session across tabs and restarts, but any XSS can read the tokens.
    // Only with persistent: true; by default they live in sessionStorage and die with the tab.
    if (setup['persistent'] === true) {
      this.oauthService.setStorage(localStorage);
    } else {
      this.oauthService.setStorage(sessionStorage);
    }
    this.oauthService.configure(config);
    // The only refresh mechanism: refreshes on token_expires (timeoutFactor). Calling it again replaces the previous one.
    // Only the access token timer: listening to the id_token one too could refresh twice per expiry
    this.oauthService.setupAutomaticSilentRefresh({}, 'access_token');
    this.oauthService.loadDiscoveryDocumentAndTryLogin().then(() => {
      this.incomingLogin();
    });
  }

  private forCurrent(str: string, tenant: string) {
    return str.replace('{{tenant}}', tenant);
  }

  private currentUrl() {
    var location = window.location;
    return location.protocol + '//' + location.host + location.pathname + location.search;
  }

  private resetCredentialsIfConfirmed(reason: IdentityErrorReason) {
    this.ui.confirmResetCredentials(reason).subscribe((ok) => {
      if (ok) {
        // Without redirect to the end_session_endpoint: only clears the stored tokens
        this.oauthService.logOut(true);
        this.resetUser();
      }
    });
  }

  private resetUser() {
    this.currentUser = {};
    this.appState.userInfo[this.name].set(this.currentUser);
    this.boostrapSubject.next();
  }

  private updateToken() {
    if (this.currentUser.authenticated) {
      const newUser = { ...this.currentUser };
      newUser.token = this.oauthService.getAccessToken();
      this.appState.userInfo[this.name].set(newUser);
    } else {
      this.incomingLogin();
    }
  }

  private incomingLogin() {
    const valid = this.oauthService.hasValidAccessToken();
    if (valid != this.logged) {
      this.logged = valid;
      if (valid) {
        this.oauthService.loadUserProfile().then((info: any) => {
          this.currentUser = {
            name: info.info.name,
            email: info.info.email,
            authenticated: true,
            token: this.oauthService.getAccessToken(),
            roles: info.info[this.rolesClaim] || ['guest'],
          };
          this.appState.userInfo[this.name].set(this.currentUser);
          this.boostrapSubject.next();
        });
      } else {
        this.resetUser();
      }
    }
  }
}
